(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5056],{62220:(e,n,t)=>{Promise.resolve().then(t.bind(t,70039))},70039:(e,n,t)=>{"use strict";t.r(n),t.d(n,{default:()=>h});var i=t(95155),a=t(12115),r=t(51238),o=t(74737),s=t(22133),d=t(98698),c=t(30014);let l=[];function h(){let[e,n]=(0,a.useState)("about");return(0,i.jsxs)("div",{children:[(0,i.jsx)("h2",{children:"Seminar on User-Centered Programming Interfaces, 2026"}),(0,i.jsxs)(c.A,{value:e,onChange:n,style:{marginBottom:"2rem"},children:[(0,i.jsx)(c.A.Item,{label:"About",value:"about"}),(0,i.jsx)(c.A.Item,{label:"Syllabus",value:"syllabus"}),(0,i.jsx)(c.A.Item,{label:"Reading List",value:"reading-list"}),(0,i.jsx)(c.A.Item,{label:"Paper Presentation",value:"presentation"}),(0,i.jsx)(c.A.Item,{label:"Revibing",value:"revibe"}),(0,i.jsx)(c.A.Item,{label:"Final Blog Post",value:"blogs"}),(0,i.jsx)(c.A.Item,{label:"Grading",value:"grading"})]}),(0,i.jsx)("div",{className:"ucpi-main",children:(()=>{switch(e){case"about":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"Programming interfaces are not just for professional programmers and CS majors. With the pervasive spread of computing technology, various programming interfaces have been designed to support different end users (e.g., scientists, artists, journalists) to communicate their intent to computers.\n\nThis course introduces students to research topics around the principles and practices of designing user-centered programming interfaces. We will explore and discuss research papers that focus on various design and interaction techniques to support programmers of various backgrounds. We will start by discussing the properties of programming interfaces and understanding programmers from various specialized domains. We will then dive into the topic of usable programming environments, including interactive programming paradigms such as structured editing, programming by demonstration, live programming, and literate programming; collaborative and inclusive programming interfaces that allow programmers to build upon each other's work; interfaces specifically designed for better learning and teaching in computer science. Finally, we discuss how AI is reshaping the future of programming interfaces.​\n\n### Course Logistics\n| Instructor | [Prof. Dr. April Wang](mailto:april.wang@inf.ethz.ch) |\n|------------|-------------------------------------------------------|\n| Time | Thu 16:15-18:00 |\n| Location | CAB G 52 |\n| Language of Instruction | English |\n| Credits | 2 Credits |\n| Course Catalogue | [VVZ](https://www.vvz.ethz.ch/Vorlesungsverzeichnis/lerneinheit.view?semkez=2026W&ansicht=LEHRVERANSTALTUNGEN&lerneinheitId=203224&lang=en) \n| Office Hours | [Booking](https://doodle.com/bp/aprilwang/office-hour) \n\n\n### Course Format\n\nThis research seminar meets weekly for 90-minute discussions on selected topics in user-centered programming interfaces. Each week, we will focus on one topic and read two papers. Students are expected to read the assigned papers in advance.\n\nEach paper will be presented by one student. As part of the presentation, the student will also **revibe** the interactive artifact described in the paper using contemporary AI-assisted or agentic programming tools, demonstrate the resulting prototype, and lead the discussion on the paper.\n\nBy the end of the semester, students will develop their revibed artifact into an **interactive blog post** on their presented topic. Students are expected to explore additional research, synthesize perspectives from the seminar discussions, and connect the topic to relevant literature. The interactive artifact should help readers understand or explore a key idea from the research.\n\nTogether, we will publish the posts on this site as a collective learning resource for future students and researchers.\n"})});case"syllabus":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"Please note that the syllabus is tentative. \nThe latest presentation schedule will be updated soon. \nWe may make small adjustments based on the guest lecture.\n\n\n| W  | D     | Topic                                   | Presenters |\n|----|-------|-----------------------------------------|------------|\n| 1  | 9.17  | Course Logistics |            |\n| 2  | 9.24  | Topic Overview: Redefining Programming |            |\n| 3  | 10.1  | Break                                   |            |\n| 4  | 10.8  | Program Understanding                   |            |\n| 5  | 10.15 | Code Editing                            |            |\n| 6  | 10.22 | End-User Programming                    |            |\n| 7  | 10.29 | Programming by Demonstration            |            |\n| 8  | 11.5  | **Guest Lecture**                       |            |\n| 9  | 11.12 | Debugging                               |            |\n| 10 | 11.19 | Managing Versions and Alternatives      |            |\n| 11 | 11.26 | Collaborative Programming               |            |\n| 12 | 12.3  | Diagramming and Animations              |            |\n| 13 | 12.10 | Teaching Programming                    |            |\n| 14 | 12.17 | Code Clustering                |            |\n"})});case"reading-list":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"Each topic pairs one paper from before the rise of LLMs with one from the LLM era. Each paper is presented by one student.\n\n#### W4 (10.8). Program Understanding\n##### Pre-LLM\n- [Code Augmenting](https://doi.org/10.1145/3173574.3174106): Jane Hoffswell, Arvind Satyanarayan, and Jeffrey Heer. 2018. Augmenting Code with In Situ Visualizations to Aid Program Understanding. In Proceedings of the 2018 CHI Conference on Human Factors in Computing Systems (CHI '18). Association for Computing Machinery, New York, NY, USA, Paper 532, 1–12.\n##### LLM-based\n- [WaitGPT](https://doi.org/10.1145/3654777.3676374): Liwenhan Xie, Chengbo Zheng, Haijun Xia, Huamin Qu, and Chen Zhu-Tian. 2024. WaitGPT: Monitoring and Steering Conversational LLM Agent in Data Analysis with On-the-Fly Code Visualization. In Proceedings of the 37th Annual ACM Symposium on User Interface Software and Technology (UIST '24). Association for Computing Machinery, New York, NY, USA, Article 119, 1–14.\n\n#### W5 (10.15). Code Editing\n##### Pre-LLM\n- [Sandblocks](https://dl.acm.org/doi/pdf/10.1145/3544548.3580785): Beckmann, T., Rein, P., Ramson, S., Bergsiek, J., & Hirschfeld, R. (2023, April). Structured Editing for All: Deriving Usable Structured Editors from Grammars. In Proceedings of the 2023 CHI Conference on Human Factors in Computing Systems (pp. 1-16).\n##### LLM-based\n- [Code Shaping](https://doi.org/10.1145/3706598.3713822): Ryan Yen, Jian Zhao, and Daniel Vogel. 2025. Code Shaping: Iterative Code Editing with Free-form AI-Interpreted Sketching. In Proceedings of the 2025 CHI Conference on Human Factors in Computing Systems (CHI '25). Association for Computing Machinery, New York, NY, USA, Article 872, 1–17.\n\n#### W6 (10.22). End-User Programming\n##### Pre-LLM\n- [Pumice](https://dl.acm.org/doi/10.1145/3332165.3347899): Li, T. J. J., Radensky, M., Jia, J., Singarajah, K., Mitchell, T. M., & Myers, B. A. (2019, October). Pumice: A multi-modal agent that learns concepts and conditionals from natural language and demonstrations. In Proceedings of the 32nd Annual ACM Symposium on User Interface Software and Technology (pp. 577-589).\n##### LLM-based\n- [Abstraction Match](https://dl.acm.org/doi/10.1145/3544548.3580817): Michael Xieyang Liu, Advait Sarkar, Carina Negreanu, Benjamin Zorn, Jack Williams, Neil Toronto, and Andrew D. Gordon. 2023. “What It Wants Me To Say”: Bridging the Abstraction Gap Between End-User Programmers and Code-Generating Large Language Models. In Proceedings of the 2023 CHI Conference on Human Factors in Computing Systems (CHI '23).\n\n#### W7 (10.29). Programming by Demonstration\n##### Pre-LLM\n- [ReCode](https://doi.org/10.1145/3472749.3474748): Wode Ni, Joshua Sunshine, Vu Le, Sumit Gulwani, and Titus Barik. 2021. ReCode: A Lightweight Find-and-Replace Interaction in the IDE for Transforming Code by Example. In The 34th Annual ACM Symposium on User Interface Software and Technology (UIST '21). Association for Computing Machinery, New York, NY, USA, 258–269.\n##### LLM-based\n- [Perpend](https://dl.acm.org/doi/pdf/10.1145/3772318.3791327): Angela Bi, Eric Rawn, Justin Lubin, and Sarah E. Chasins. 2026. Programming by Scaffolded Demonstration with Perpend. In Proceedings of the 2026 CHI Conference on Human Factors in Computing Systems (CHI '26).\n\n#### W8 (11.5). Guest Lecture\n- TBD\n\n#### W9 (11.12). Debugging\n##### Pre-LLM\n- [Log-it](https://dl.acm.org/doi/10.1145/3544548.3581403): Jiang, P., Sun, F., & Xia, H. (2023, April). Log-it: Supporting programming with interactive, contextual, structured, and visual logs. In Proceedings of the 2023 CHI Conference on Human Factors in Computing Systems (pp. 1-16).\n##### LLM-based\n- [AGDebugger](https://dl.acm.org/doi/10.1145/3706598.3713581): Epperson, W., Bansal, G., Dibia, V. C., Fourney, A., Gerrits, J., Zhu, E., & Amershi, S. (2025, April). Interactive debugging and steering of multi-agent AI systems. In Proceedings of the 2025 CHI Conference on Human Factors in Computing Systems (pp. 1-15).\n\n#### W10 (11.19). Managing Versions and Alternatives\n##### Pre-LLM\n- [Code Gathering](https://dl.acm.org/doi/10.1145/3290605.3300500): Head, A., Hohman, F., Barik, T., Drucker, S. M., & DeLine, R. (2019, May). Managing messes in computational notebooks. In Proceedings of the 2019 CHI Conference on Human Factors in Computing Systems (pp. 1-12).\n##### LLM-based\n- [Spellburst](https://doi.org/10.1145/3586183.3606719): Tyler Angert, Miroslav Suzara, Jenny Han, Christopher Pondoc, and Hariharan Subramonyam. 2023. Spellburst: A Node-based Interface for Exploratory Creative Coding with Natural Language Prompts. In Proceedings of the 36th Annual ACM Symposium on User Interface Software and Technology (UIST '23). Association for Computing Machinery, New York, NY, USA, Article 100, 1–22.\n\n#### W11 (11.26). Collaborative Programming\n##### Pre-LLM\n- [Collabode](https://dl.acm.org/doi/10.1145/2047196.2047215): Goldman, M., Little, G., & Miller, R. C. (2011, October). Real-time collaborative coding in a web IDE. In Proceedings of the 24th Annual ACM Symposium on User Interface Software and Technology (pp. 155-164).\n##### LLM-based\n- [Coprompt](https://dl.acm.org/doi/10.1145/3613904.3642212): Feng, L., Yen, R., You, Y., Fan, M., Zhao, J., & Lu, Z. (2024, May). Coprompt: Supporting prompt sharing and referring in collaborative natural language programming. In Proceedings of the 2024 CHI Conference on Human Factors in Computing Systems (pp. 1-21).\n\n#### W12 (12.3). Diagramming and Animations\n##### Pre-LLM\n- [EDDIE](https://dl.acm.org/doi/10.1145/3025453.3025467): Sarracino, J., Barrios-Arciga, O., Zhu, J., Marcus, N., Lerner, S., & Wiedermann, B. (2017, May). User-guided synthesis of interactive diagrams. In Proceedings of the 2017 CHI Conference on Human Factors in Computing Systems (pp. 195-207).\n##### LLM-based\n- [Drawtalking](https://dl.acm.org/doi/10.1145/3654777.3676334): Rosenberg, K. T., Kazi, R. H., Wei, L. Y., Xia, H., & Perlin, K. (2024, October). Drawtalking: Building interactive worlds by sketching and speaking. In Proceedings of the 37th Annual ACM Symposium on User Interface Software and Technology (pp. 1-25).\n\n#### W13 (12.10). Teaching Programming\n##### Pre-LLM\n- [Torii](https://dl.acm.org/doi/10.1145/3313831.3376798): Head, A., Jiang, J., Smith, J., Hearst, M. A., & Hartmann, B. (2020, April). Composing flexibly-organized step-by-step tutorials from linked source code, snippets, and outputs. In Proceedings of the 2020 CHI Conference on Human Factors in Computing Systems (pp. 1-12).\n##### LLM-based\n- [CodeAid](https://dl.acm.org/doi/pdf/10.1145/3613904.3642773): Majeed Kazemitabaar, Runlong Ye, Xiaoning Wang, Austin Zachary Henley, Paul Denny, Michelle Craig, and Tovi Grossman. 2024. CodeAid: Evaluating a Classroom Deployment of an LLM-based Programming Assistant that Balances Student and Educator Needs. In Proceedings of the 2024 CHI Conference on Human Factors in Computing Systems (CHI '24). Association for Computing Machinery, New York, NY, USA, Article 650, 1–20.\n\n#### W14 (12.17). Code Clustering (Backup)\n##### Pre-LLM\n- [VizProg](https://dl.acm.org/doi/10.1145/3544548.3581516): Zhang, A. G., Chen, Y., & Oney, S. (2023, April). VizProg: Identifying misunderstandings by visualizing students’ coding progress. In Proceedings of the 2023 CHI Conference on Human Factors in Computing Systems (pp. 1-16).\n##### LLM-based\n- [StuGPTViz](https://doi.org/10.1109/TVCG.2024.3456363): Zixin Chen, Jiachen Wang, Meng Xia, Kento Shigyo, Dingdong Liu, Rong Zhang, and Huamin Qu. 2025. StuGPTViz: A Visual Analytics Approach to Understand Student-ChatGPT Interactions. IEEE Transactions on Visualization and Computer Graphics 31, 1 (Jan. 2025), 908–918.\n"})});case"presentation":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"Each week, we will focus on one topic in user-centered programming interfaces and read two papers: one from before the rise of LLMs and one from the LLM era. Each paper will be presented by one student.\n\nAs part of the presentation, you will also **revibe** the interactive prototype described in your assigned paper.\n\n#### Presentation Format\n\n**1. Background and Related Work ~10 min**\n\nIntroduce the problem addressed by the paper and situate the work within the broader research landscape.\n\nCover:\n\n* What problem does the paper address?\n* What was the state of the art at the time?\n* What is the key idea or contribution?\n* How does the work relate to the broader topic of the week?\n\n**2. Live Demo of the Revibed Prototype ~15 min**\n\nBefore class, use contemporary AI-assisted or agentic coding tools to reimplement the interactive prototype described in the paper.\n\nDuring the presentation, give a live demonstration of your revibed prototype.\n\nFocus on:\n\n* the core interactions and functionality described in the paper;\n* how the system works from the user's perspective;\n* which parts of the original system you were able to reproduce;\n* any ambiguities or missing implementation details you encountered while revibing the system.\n\n\n**3. Evaluation in the Original Paper ~5 min**\n\nPresent how the authors evaluated the original system.\n\nExplain:\n\n* What research questions or hypotheses did the evaluation address?\n* What evaluation method did the authors use?\n* Who participated, if applicable?\n* What tasks, conditions, and measures were used?\n* What were the main findings?\n* What does the evaluation establish about the system, and what remains uncertain?\n\n**4. Discussion ~15 min**\n\nLead and moderate the discussion. Prepare a few prompt questions in advance, keep the conversation moving, invite everyone to contribute, and connect the discussion back to the paper, the system, or your revibing experience."})});case"revibe":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:'**Revibing** is the practice of reimplementing an interactive system described in a research paper using AI-assisted and agentic coding tools. The idea is introduced in [Revibing Code from Papers: Reimplementing HCI Artifacts](https://arxiv.org/abs/2608.00450) (Adar et al., 2026) and is the subject of the [Revibing HCI](https://revibe-hci.github.io/) workshop at UIST 2026.\n\n#### Why revibe?\n\nMost technical HCI research is published as a paper and a video figure. The software itself is usually gone: "software artifacts for most technical HCI projects are unavailable, which makes it hard to extend prior work, use them as strong baselines, or replicate results."\n\nThis is a particular problem for a seminar on programming interfaces, where the contribution of a paper is often an *interaction* rather than a result. A screenshot of a structured editor or a sketch-based code tool tells you what the interface looks like, but not what it feels like to use, where it breaks down, or which details the authors had to get right for it to work at all.\n\nAgentic coding tools have made it realistic to rebuild these systems in a few hours. Adar et al. introduce **revibeability** as a measure of how successfully a system can be reimplemented from its paper alone; across ten recent UIST systems rebuilt with tools such as Claude, Cursor, and Gemini, the reported mean revibeability was 94.1%, in many cases producing code good enough to serve as a strong baseline.\n\n#### What you will do\n\nFor your assigned paper, rebuild the interactive prototype before your presentation and demonstrate it live in class. Your revibe does not need to be a complete or production-quality system. Aim to reproduce:\n\n* the core interactions the paper claims as its contribution;\n* enough of the interface that the audience can see how the system behaves from a user\'s perspective;\n* at least one example or scenario from the paper, so we can compare your version against what the authors reported.\n\nThe goal is to **reproduce the original interaction, not to redesign or improve it**. If you have ideas for extensions, save them for the discussion.\n\n#### What to pay attention to\n\nRevibing is useful here because of what goes wrong, not only what works. While rebuilding, keep notes on:\n\n* **Underspecified details.** Which design decisions did you have to make yourself because the paper did not say? These gaps are often where the real design work lives.\n* **What resisted reimplementation.** Reported failure points include drag-and-drop interactions, dependencies on models or services that no longer exist, and agent-introduced scope creep.\n* **What the paper made look easy.** If something took you far longer than the paper suggests, that is worth reporting.\n* **Where your version diverges.** Be explicit about what you left out and why.\n\nBring these observations to the discussion. Your experience rebuilding the system is evidence about the design that the paper alone cannot give us.\n\n#### Further reading\n\n- [Revibing Code from Papers: Reimplementing HCI Artifacts](https://arxiv.org/abs/2608.00450): Eytan Adar, Yoonjoo Lee, Nina Lei, Q. Vera Liao, and Weirui Peng. 2026. arXiv:2608.00450.\n- [Revibing HCI](https://revibe-hci.github.io/): workshop at UIST 2026\n'})});case"blogs":return(0,i.jsxs)("div",{children:[(0,i.jsx)("div",{className:"blog-grid",children:l.map(e=>(0,i.jsxs)("a",{href:"".concat("/peachlab.inf.ethz.ch","/teaching/ucpi2026/blog/").concat(e.slug,"/"),className:"blog-card",children:[(0,i.jsx)("h4",{children:e.title}),(0,i.jsx)("div",{className:"author",children:e.author}),(0,i.jsx)("div",{className:"desc",children:e.desc})]},e.slug))}),(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"#### What is a blog post?\n\nThe final blog post should give any computer science student, even if they are new to the topic, a clear and engaging introduction to the research area.\n\nIt should highlight relevant research, include your own perspective, and use your **revibed artifact as part of the explanation**. The artifact should help readers understand, explore, or experience an important idea from the topic.\n\nThis is not a paper summary or a literature review. Write in an accessible, conversational style for a broad technical audience.\n\nExamples:\n\n* https://cacm.acm.org/section/blogcacm/\n* https://cacm.acm.org/blogcacm/the-evolution-of-user-interface-design/\n* https://cacm.acm.org/research/end-user-software-engineering/\n* Last year's posts: https://peachlab.inf.ethz.ch/teaching/ucpi2025/\n\n#### Is there a template or structure?\n\nThere is no required structure. Please keep the written content around **800–1200 words**, and provide your name and a short bio for the course website.\n\nA strong post should:\n\n* clearly motivate the research topic;\n* demonstrate depth and synthesis beyond summarizing individual papers;\n* use the interactive artifact meaningfully;\n* be clear and engaging for a broad audience;\n* integrate and cite relevant sources; and\n* optionally offer forward-looking ideas about the future of programming interfaces.\n\n#### Should I find additional papers on the topic?\n\nYes. Use the seminar readings as a starting point, but explore additional relevant work.\n\nThis is a targeted discussion rather than a literature review, so quality matters more than quantity. Please include **at least five substantive sources** and cite them using APA style.\n\n#### Submission\n\n* Due: **February 1, 2027**\n* Submit the blog post and interactive artifact as a PR to: TBD"})]});case"grading":return(0,i.jsx)("div",{children:(0,i.jsx)(r.oz,{rehypePlugins:[o.A,d.A],remarkPlugins:[s.A],children:"#### Grading Rubric\n- Presentation: 50%\n- Participation in discussions: 20%\n- Final interactive blog post: 30%\n\n#### Grading Criteria for the Presentation\nEach paper is presented by a single student. The presenter should assume that everyone has already read the paper before class.\n\n- Understanding and contextualization (20 points): Does the presenter demonstrate a strong understanding of the paper, its contribution, and how it fits into the broader research area?\n- Revibed prototype (30 points): Does the prototype faithfully capture the core interaction and functionality of the original system? Does the presenter reflect on ambiguities, limitations, or assumptions involved in revibing it?\n- Analysis (20 points): Does the presenter provide insights beyond summarizing the paper, including connections to related work or broader themes?\n- Presentation quality (10 points): Is the presentation clear, well-organized, and engaging?\n- Discussion facilitation (20 points): Does the presenter prepare thoughtful prompts and facilitate an engaging and balanced discussion?\n\n#### Grading Criteria for Participation\n- The instructor team will keep track of participation during each lecture.\n- Participation should demonstrate engagement with the readings and contribute constructively to class discussion.\n- The presenter will select five MVP audience members, who each receive one bonus participation point.\n\n#### Grading Criteria for the Final Interactive Blog Post\n- Motivation and framing (15 points): Is the research topic clearly motivated and its relevance explained?\n- Depth and synthesis (30 points): Does the post demonstrate deep understanding and provide insights beyond summarizing individual papers?\n- Interactive artifact (30 points): Does the artifact meaningfully help readers understand or explore the research topic? Is it well integrated into the post?\n- Clarity and engagement (15 points): Is the post accessible, coherent, and engaging for a broad computer science audience?\n- Writing and sources (10 points): Is the post well-written and supported by appropriate, well-integrated sources?\n\nBonus — Forward-thinking (+10 points): Does the post offer original or creative perspectives on the future of programming interfaces?\n"})});default:return null}})()})]})}t(70243)},70243:()=>{}},e=>{e.O(0,[8764,2951,1238,14,8387,8441,1255,7358],()=>e(e.s=62220)),_N_E=e.O()}]);